from itertools import product

# Smart search: values can't be too large
# x[i] counts occurrences of i, so sum(x) = 9
# We know x[4] = 0

# Use backtracking
def solve():
    seq = [None] * n
    seq[4] = 0  # fixed constraint

    def backtrack(pos):
        if pos == n:
            if is_magic_sequence(seq):
                return seq[:]
            return None
        if pos == 4:
            return backtrack(pos + 1)

        for val in range(n):
            seq[pos] = val
            # Pruning: check partial consistency
            result = backtrack(pos + 1)
            if result:
                return result
        seq[pos] = None
        return None

    return backtrack(0)

# Better: enumerate more carefully
for seq in product(range(n), repeat=n):
    if seq[4] != 0:
        continue
    if is_magic_sequence(list(seq)):
        solutions.append(seq)

print("Solutions found:", solutions)
